	public class MEEmrActionsController:BaseBusinessController
	{
		public MEEmrActionsController()
		{
			dal= new DALBaseProvider("MEEmrActions",typeof(MEEmrActionsInfo));
		}
		public bool CheckActionUsed(int actionID)
		{
			String query = String.Format("select count(1) from MEEmrTemplateActions where AAStatus = 'alive' and FK_MEEmrActionID = {0}", actionID);
			int iCount = 0;
			System.Data.Common.DbCommand cmd = SqlDatabaseHelper.GetQuery(query);
			DataSet ds = SqlDatabaseHelper.RunQuery(cmd);
			if (ds.Tables.Count > 0)
			{
				if (ds.Tables[0].Rows.Count > 0)
				{
					iCount = Convert.ToInt32(ds.Tables[0].Rows[0][0]);
				}
			}
			return iCount > 0;
		}
	}
	#endregion
